<script setup lang="ts">
import {t} from "../i18n"
import { reactive, ref, watch, computed } from 'vue'
import { themeStyle } from '../domain'
import { useQuasar } from 'quasar'
import { useCms } from '../store'
import { api, send } from '../api'
import Icon from './Icon.vue'
import BlockRenderer from './BlockRenderer.vue'
const cms=useCms(),q=useQuasar(),theme=ref('Evergreen'),tab=ref('Theme'),saving=ref(false),a=reactive<Record<string,any>>({}),presets=ref<any[]>([])
watch(()=>cms.selected,site=>{if(site){theme.value=site.theme;for(const key of Object.keys(a))delete a[key];Object.assign(a,{secondary:'#dce9d9',accent:'#d9edba',surface:'#ffffff',heading:'#193c30',headingFont:'Georgia',fontSize:14,lineHeight:1.7,spacing:65,shadow:'none'},site.appearance)}},{immediate:true})
watch(()=>cms.selectedId,async()=>{if(cms.selectedId){try{presets.value=await api('/websites/'+cms.selectedId+'/theme-presets')}catch(e:any){q.notify({type:'negative',message:t(e.message)})}}},{immediate:true})
const themes={Evergreen:'#286b54',Editorial:'#855039',Studio:'#62588b',Scholar:'#274e75'}
const style=computed(()=>themeStyle(a,window.matchMedia('(prefers-color-scheme: dark)').matches))
async function save(){saving.value=true;try{await api('/websites/'+cms.selectedId+'/appearance',send('PUT',{theme:theme.value,appearance:a}));await cms.load();q.notify({type:'positive',message:t('Your new look is live across the website.')})}catch(e:any){q.notify({type:'negative',message:t(e.message)})}finally{saving.value=false}}
function savePreset(){q.dialog({title:t('Save a reusable appearance preset'),message:t('This saves your current preview without changing the live website.'),prompt:{model:'My custom look',type:'text'},cancel:true}).onOk(async(name:string)=>{try{await api('/websites/'+cms.selectedId+'/theme-presets',send('POST',{name,theme:theme.value,appearance:a}));presets.value=await api('/websites/'+cms.selectedId+'/theme-presets');q.notify({type:'positive',message:t('Preset saved. Load it to preview, then Save appearance to activate.')})}catch(e:any){q.notify({type:'negative',message:t(e.message)})}})}
function removePreset(id:number){q.dialog({title:t('Delete this preset?'),message:t('The active website appearance will not change.'),cancel:true}).onOk(async()=>{try{await api('/websites/'+cms.selectedId+'/theme-presets/'+id,{method:'DELETE'});presets.value=presets.value.filter(p=>p.id!==id)}catch(e:any){q.notify({type:'negative',message:t(e.message)})}})}

function reset(){q.dialog({title:t('Reset appearance?'),message:t('Unsaved color and layout changes will be replaced with the selected theme defaults.'),cancel:true}).onOk(()=>Object.assign(a,{primary:themes[theme.value as keyof typeof themes],background:'#faf9f6',text:'#263d35',font:'Inter',radius:12,container:1200,mode:'light'}))}
</script>
<template><div class="appearance-layout"><section class="appearance-controls panel"><div class="section-heading"><h2>{{ $t("Make it yours") }}</h2><Icon name="SlidersHorizontal"/></div><div class="customizer-tabs"><button v-for="t in ['Theme','Colors','Typography','Layout','Presets']" :class="{active:tab===t}" @click="tab=t">{{ $t(t) }}</button></div><template v-if="tab==='Theme'"><h3>{{ $t("A foundation for your brand") }}</h3><p class="muted">{{ $t("Four distinct personalities. Infinite possibilities.") }}</p><div class="theme-grid"><button v-for="(color,name) in themes" :class="{selected:theme===name}" @click="theme=String(name);a.primary=color"><div class="theme-swatch" :style="{background:color}"><span></span><i></i><i></i></div><strong>{{ name }}</strong><Icon v-if="theme===name" name="CircleCheck" :size="16"/></button></div><h3>{{ $t("Appearance mode") }}</h3><q-btn-toggle v-model="a.mode" no-caps unelevated spread toggle-color="primary" :options="[{label:'Light',value:'light'},{label:'Dark',value:'dark'},{label:'System',value:'system'}]"/></template><template v-if="tab==='Colors'"><h3>{{ $t("A palette with personality") }}</h3><label v-for="(label,key) in {primary:'Primary & buttons',secondary:'Secondary',accent:'Accent',background:'Page background',surface:'Card surfaces',text:'Body text',heading:'Headings'}" class="color-field"><span>{{ $t(label) }}</span><input type="color" v-model="a[key]"><code>{{ a[key] }}</code></label><div class="info-note">{{ $t("Changes preview instantly. Save to apply them to your published website.") }}</div></template><template v-if="tab==='Typography'"><h3>{{ $t("Find your voice") }}</h3><q-select emit-value map-options outlined v-model="a.font" :options="$translatedOptions(['Inter','Georgia','Arial'])" :label="$t('Website font')"/><q-select emit-value map-options outlined v-model="a.headingFont" :options="$translatedOptions(['Inter','Georgia','Arial'])" :label="$t('Heading font')"/><label class="field-label">{{ $t("Body size ·") }} {{ a.fontSize }} {{ $t("px") }}</label><q-slider v-model="a.fontSize" :min="12" :max="22"/><label class="field-label">{{ $t("Line height ·") }} {{ a.lineHeight }}</label><q-slider v-model="a.lineHeight" :min="1.2" :max="2.2" :step="0.1"/><p class="type-sample" :style="{fontFamily:a.font}">{{ $t("The art of") }}<br>{{ $t("being different.") }}</p><p class="muted">{{ $t("One consistent font system, from navigation to footer. Native script fallbacks support Dari, Pashto, and Arabic.") }}</p></template><template v-if="tab==='Layout'"><h3>{{ $t("A little breathing room") }}</h3><label class="field-label">{{ $t("Corner radius ·") }} {{ a.radius }} {{ $t("px") }}</label><q-slider v-model="a.radius" :min="0" :max="40" color="primary"/><label class="field-label">{{ $t("Container width ·") }} {{ a.container }} {{ $t("px") }}</label><q-slider v-model="a.container" :min="800" :max="1600" :step="20" color="primary"/><label class="field-label">{{ $t("Section spacing ·") }} {{ a.spacing }} {{ $t("px") }}</label><q-slider v-model="a.spacing" :min="20" :max="100"/><q-select emit-value map-options outlined v-model="a.shadow" :options="$translatedOptions(['none','soft','raised'])" :label="$t('Card shadow')"/><p class="muted">{{ $t("Content adapts automatically to desktop, tablet, and mobile screens.") }}</p></template><template v-if="tab==='Presets'"><h3>{{ $t("Your saved looks") }}</h3><p class="muted">{{ $t("Load a preset to preview it. Save appearance to activate. Save again with a new name to duplicate a look.") }}</p><div v-for="p in presets" :key="p.id" class="preset-row"><span class="preset-color" :style="{background:p.appearance.primary}"></span><strong>{{ p.name }}</strong><button class="text-link" @click="theme=p.theme;Object.assign(a,p.appearance)">{{ $t("Preview") }}</button><button class="icon-btn danger" @click="removePreset(p.id)" :aria-label="$t('Delete preset')"><Icon name="Trash2" :size="14"/></button></div><p v-if="!presets.length" class="empty-text">{{ $t("Save your first custom look below.") }}</p><button class="btn secondary" @click="savePreset"><Icon name="BookmarkPlus" :size="16"/>{{ $t("Save current look as preset") }}</button></template><div class="appearance-save"><button class="text-link" @click="reset"><Icon name="RotateCcw" :size="14"/>{{ $t("Reset theme") }}</button><q-btn unelevated color="primary" :label="$t('Save appearance')" :loading="saving" @click="save"/></div></section><section class="appearance-preview panel"><div class="preview-toolbar"><span><span class="status-dot"></span> {{ $t("LIVE PREVIEW") }}</span><Icon name="Monitor" :size="18"/><span>{{ $t("Changes aren’t saved yet") }}</span></div><div class="public-site miniature-site" :style="style"><header class="public-header"><a><Icon name="Leaf"/>{{ cms.selected?.name }}</a><nav><a>{{ $t("Our story") }}</a><a>{{ $t("Contact") }}</a></nav></header><BlockRenderer :blocks="[{id:'preview',type:'Hero',title:'Thoughtfully made.\nBeautifully different.',text:cms.selected?.description||'A space for your next great idea.',image:cms.selected?.image,button:'Discover more'},{id:'preview-text',type:'Text',title:'Good things start here.',text:'Your story deserves a beautiful home.'}]"/><footer class="public-footer">© {{ new Date().getFullYear() }} {{ cms.selected?.name }}</footer></div></section></div></template>
